(root/'MODULE-STATUS.json').write_text(json.dumps(module,indent=2)+'\n',encoding='utf-8')
names=['README.md','adapter.py','evidence.py','prepare_job.py','plan_job.py','selftest.py','seal_bridge.py','tools/Scene.ps1','tools/Scene-cancellation.patch','WRAPPER-PATCH.json','hud-startup-job.json','bindings.proposed.json','COMPILE-ADOPTION-PENDING.json','PLAN.json','PLAN-RECEIPT.json','SELFTEST-RESULT.json','MODULE-STATUS.json']
result={'status':'SOURCE_ONLY_READY_NATIVE_BLOCKED_BY_USER_HOLD_AND_PENDING_QUALIFICATION','files':[{'relative':n,'sha256':sha(root/n),'bytes':(root/n).stat().st_size} for n in names],'nativeCompile':'NOT_TESTED','nativeRuntime':'NOT_TESTED','adapterMainInvoked':False,'wrapperInvoked':False,'nativeStarted':False,'GUIOrRecorderAction':False,'leaseMutated':False,'DWrite':False,'liveRegistryChanged':False,'sourceFileCountVerified':sum(r['files'] for r in plan['completeClosures']),'blocker':{'action':'Execute first native HUD startup/capture qualification through authoritative harness','target':'Existing hudQA GEP_ApprovedRender705 scene','state':'PENDING_USER_RESUME_AND_NATIVE_QUALIFICATION','reason':'Explicit user runtime hold; no automatic resume. Real exact-stage compile/adoption, wrapper cancellation/hold/closure native qualification still missing.'},'excluded':['__pycache__','gep-bridge-offline-*','plan-history']}
(root/'DELIVERABLE-MANIFEST.json').write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8');print(json.dumps({'status':result['status'],'files':len(names),'manifestSHA256':sha(root/'DELIVERABLE-MANIFEST.json'),'sourceFileCountVerified':result['sourceFileCountVerified']}))
